pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount, uint256 lockTime) public {
        // Restrict to admissible domain: sender != zero, amount > 0 to add value, lockTime isn't farther than ~100 years
        vm.assume(sender != address(0));
        amount = bound(amount, 1, 1000000 ether);
        lockTime = bound(lockTime, 0, 365 days * 100);

        // Initialize the contract so SetMinSum/SetLogFile are not callable and we can Put
        c.Initialized();

        // Give the sender enough ether
        vm.deal(sender, amount);

        // Record balance before Put
        uint256 balanceBefore = address(c).balance;

        // Prank as sender and call Put with Ether
        vm.prank(sender);
        c.Put{value: amount}(lockTime);

        // After Put, the sender's recorded balance MUST equal the actual ETH increase the contract received
        // (contract balance after - contract balance before) plus any previous recorded balance (which is 0 for first call).
        // The simpler rule: the recorded balance for sender must equal the total ether sent by sender.
        // To make it general: c.Acc(sender).balance == amount (since no previous balance).
        // Actually the general invariant: after any Put, the sender's balance = sender's total contributed ether.
        // We derive it as: recorded balance equals the delta of contract's balance attributable to that sender.
        // Since there are no other sources of Ether (no other payable functions except fallback which calls Put(0)),
        // and only the sender's Put increases contract balance for that sender, the recorded balance for sender
        // must equal the amount sent in this Put call (if first call) or amount + previous recorded balance (if multiple).
        // For simplicity, assert that the recorded balance for sender equals the amount sent (since we only call once).
        // To be fully universal: recorded balance for sender >= amount (from this call) AND recorded balance for sender
        // equals contract's total balance (if it's the only sender) - but we need a general property across any sequence.
        // Best invariant that captures the bug: Acc(sender).balance == address(c).balance - balanceBefore (since no other senders).
        // Actually universal: Acc(sender).balance >= amount, because the mutant balance stays 0.
        // But we need a property that always holds for correct and fails for bug. The correct C always increments balance by amount;
        // the buggy C never increments it, so balance stays 0. So a property: Acc(sender).balance == amount (if first call).
        // But we need a property that holds for ALL fuzz inputs, including repeated calls? We can't enforce only one call.
        // Instead, the property: Acc(sender).balance > 0 (since amount > 0). For correct, always true; for buggy, always false.
        // Even better: assert that Acc(sender).balance == amount.
        // However if the fuzzer calls Put multiple times in some test, the property must still hold universally? No, the test function
        // is called per fuzz run; each run has one sender and one amount. So we can assert Acc(sender).balance == amount.
        ( , uint recordedBalance) = c.Acc(sender);
        assertTrue(recordedBalance == amount);
    }
}

