pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 lockTime) public {
        // Bound amount to avoid overflow and keep it reasonable
        amount = bound(amount, 1, 1 ether);
        // Ensure lockTime doesn't overflow block.timestamp
        lockTime = bound(lockTime, 0, type(uint256).max - block.timestamp);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deal Ether to this test contract as msg.sender
        vm.deal(address(this), amount);

        // Deposit
        c.Put{value: amount}(lockTime);

        // Get the recorded balance for this address
        (uint unlockTime, uint recordedBalance) = c.Acc(address(this));

        // Invariant: after every Put call, the contract's Ether balance must be >= the sum of all recorded balances
        // The bug adds 1 extra wei to the recorded balance, making recordedBalance > address(c).balance potentially
        uint contractBalance = address(c).balance;
        emit log_named_uint("recordedBalance", recordedBalance);
        emit log_named_uint("contractBalance", contractBalance);

        assertTrue(contractBalance >= recordedBalance);
    }
}

