pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstLock, uint256 secondLock, uint8 fuzzKey) public {
        // Keep lock times in reasonable range to avoid overflow and keep test fast
        firstLock = bound(firstLock, 1, 365 days);
        secondLock = bound(secondLock, 1, 365 days);
        // Ensure second lock creates a later expiry than the first
        vm.assume(secondLock > firstLock);
        address actor = address(uint160(fuzzKey | 0x1000)); // deterministic non-zero address

        // Initialize contract
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));

        // First deposit with firstLock
        vm.deal(actor, 100 ether);
        vm.startPrank(actor);
        c.Put{value: 1 ether}(firstLock);
        vm.stopPrank();

        uint256 unlockAfterFirst = c.Acc(actor).unlockTime;

        // Second deposit with larger lock time
        vm.startPrank(actor);
        c.Put{value: 2 ether}(secondLock);
        vm.stopPrank();

        uint256 unlockAfterSecond = c.Acc(actor).unlockTime;

        // The unlock time after second put must be >= unlock after first put.
        // In the correct contract, the second put extends unlock time to block.timestamp+secondLock > block.timestamp+firstLock,
        // so unlockAfterSecond > unlockAfterFirst. The mutant never updates unlock time, so unlockAfterSecond == unlockAfterFirst.
        assertTrue(unlockAfterSecond > unlockAfterFirst);
    }
}

